// ด่าน ③ Frequency cap (≤2/วัน, ≤5/สัปดาห์) | ด่าน ④ Topic relevance | ด่าน ⑤ ไม่เคยส่งคลิปนี้
const res = $input.first().json || {};
const leads = Array.isArray(res) ? res : (res.leads || res.candidates || res.data || []);
const videos = Array.isArray(res.videos) ? res.videos : (res.library || []);
const CAP_DAY = Number((res.caps && res.caps.perDay) || 2);
const CAP_WEEK = Number((res.caps && res.caps.perWeek) || 5);
const out = [];
const skipped = { consent: 0, cap: 0, noClip: 0 };
for (const l of leads) {
  const interests = (l.interests || l.topics || []).map(function (t) { return String((t && t.topic) || t).toLowerCase(); });
  const sentToday = Number(l.sentToday || l.sentTodayCount || 0) || 0;
  const sentThisWeek = Number(l.sentThisWeek || l.sentThisWeekCount || 0) || 0;
  const lastSent = l.lastSentVideoIds || l.sentVideoIds || [];
  const consentOk = l.consentMarketing !== false && l.unsubscribed !== true && l.optOut !== true;
  const capOk = sentToday < CAP_DAY && sentThisWeek < CAP_WEEK;
  const candidates = videos.filter(function (v) {
    if (String(v.status || 'ACTIVE').toUpperCase() !== 'ACTIVE') return false;
    if (lastSent.indexOf(v.videoId) !== -1) return false;
    const topic = String(v.topic || '').toLowerCase();
    const kw = (v.keywords || []).map(function (k) { return String(k).toLowerCase(); });
    if (!interests.length) return true;
    return interests.some(function (i) {
      return (topic && (topic.indexOf(i) !== -1 || i.indexOf(topic) !== -1))
        || kw.some(function (k) { return k.indexOf(i) !== -1 || i.indexOf(k) !== -1; });
    });
  }).slice(0, 8).map(function (v) {
    return { videoId: v.videoId, title: v.title, topic: v.topic, url: v.url, cta: v.cta || null };
  });
  if (!consentOk) { skipped.consent++; continue; }
  if (!capOk) { skipped.cap++; continue; }
  if (!candidates.length) { skipped.noClip++; continue; }
  out.push({ json: {
    prospectId: l.prospectId || l.id, name: l.name || null, channel: l.channel || 'LINE',
    interests: interests, sentToday: sentToday, sentThisWeek: sentThisWeek,
    caps: { perDay: CAP_DAY, perWeek: CAP_WEEK }, lastSentVideoIds: lastSent,
    videoCandidates: candidates
  }, pairedItem: { item: 0 } });
}
if (out.length === 0) return [{ json: { none: true, reason: 'ไม่มีรายการที่ผ่านด่านในรอบนี้', skipped: skipped, leadsChecked: leads.length } }];
return out;

// อ่านคำแนะนำจาก AI + บังคับว่าต้องเป็นคลิปที่อยู่ในลิสต์ที่ผ่านด่านแล้วเท่านั้น
const leads = $('คัดกรอง Topic + Frequency Cap (≤2/วัน ≤5/สัปดาห์)').all();
const items = $input.all();
const out = [];
items.forEach(function (it, i) {
  const lead = (leads[i] && leads[i].json) || {};
  if (lead.none || !lead.prospectId) return;
  const raw = String(it.json.answer || it.json.text || it.json.content || '');
  const m = raw.match(/\{[\s\S]*\}/);
  let parsed = null;
  if (m) { try { parsed = JSON.parse(m[0]); } catch (e) { parsed = null; } }
  const ids = (lead.videoCandidates || []).map(function (v) { return v.videoId; });
  let pick = parsed && (parsed.videoId || parsed.video_id);
  if (pick && ids.indexOf(pick) === -1) pick = null;   // AI เลือกคลิปนอกลิสต์ = ไม่รับ
  if (!pick && ids.length) pick = ids[0];              // fallback: คลิปแรกที่เกี่ยวข้อง
  if (!pick) return;
  const clip = (lead.videoCandidates || []).filter(function (v) { return v.videoId === pick; })[0] || {};
  out.push({ json: {
    prospectId: lead.prospectId, channel: lead.channel, videoId: pick,
    videoTitle: clip.title || null, videoUrl: clip.url || null, cta: clip.cta || null,
    reason: (parsed && parsed.reason) ? String(parsed.reason).slice(0, 300) : 'ตรงกับความสนใจ: ' + (lead.interests || []).join(', '),
    confidence: (parsed && Number(parsed.confidence)) ? Math.max(0, Math.min(1, Number(parsed.confidence))) : 0.6,
    message: (parsed && parsed.message) ? String(parsed.message).slice(0, 600) : null,
    aiOk: !!parsed, caps: lead.caps, sentToday: lead.sentToday, sentThisWeek: lead.sentThisWeek,
    at: new Date().toISOString()
  }, pairedItem: { item: i } });
});
if (out.length === 0) return [{ json: { none: true, reason: 'ไม่มีคำแนะนำที่ต้องบันทึกในรอบนี้' } }];
return out;

// สรุปผลการบันทึกคำแนะนำ
const all = $('บันทึกคำแนะนำ (/api/recommend)').all();
let okCount = 0, failCount = 0, firstError = null;
for (const it of all) {
  const j = it.json || {};
  const c = j.statusCode === undefined ? null : Number(j.statusCode);
  const ok = j.ok === true || (c !== null && c >= 200 && c < 300);
  if (ok) okCount++;
  else { failCount++; if (!firstError) firstError = String(j.error || j.message || ('HTTP ' + c)).slice(0, 300); }
}
return [{ json: {
  ok: failCount === 0, workflow: '04-video-recommendation', stage: 'recommend',
  detail: 'บันทึกคำแนะนำสำเร็จ ' + okCount + ' ราย / ล้มเหลว ' + failCount + ' ราย' + (firstError ? ' — ' + firstError : ''),
  total: all.length, succeeded: okCount, failed: failCount, firstError: firstError,
  alertText: (failCount === 0 ? 'Video Recommendation รอบล่าสุดสำเร็จ ' : 'แจ้งเตือน: Video Recommendation ล้มเหลว ') + okCount + ' ราย',
  at: new Date().toISOString()
} }];
